const $=id=>document.getElementById(id);let token='',epoch=0;
const labels={requests:'Demandes',crm:'Opportunités',consultants:'Consultants',tenders:'Appels d’offres',quotes:'Devis'};
let controlData=null;
const metrics=[['budget_revenue','CA budget'],['budget_cost','Coût budget'],['validated_revenue','Facturable validé'],['validated_cost','Coût validé'],['validated_margin','Marge opérationnelle'],['cost_remaining','Solde budget coûts'],['revenue_gap','Écart CA'],['margin_gap','Écart marge / budget'],['invoiced','Créances émises'],['received','Encaissé'],['receivable','À encaisser'],['overdue','En retard'],['unbilled','Non facturé'],['allocated_outflows','Décaissements affectés'],['allocated_cash_flow','Flux net affecté'],['margin_rate','Marge / CA (%)'],['budget_cost_used_rate','Budget coût consommé (%)'],['collection_rate','Taux encaissé (%)']];
function notice(s){$('notice').textContent=s}
function elem(tag,text){const e=document.createElement(tag);e.textContent=text;return e}
const saasFinance=elem('section','');saasFinance.className='workflow-section';saasFinance.id='saas-finance';$('workspace').append(saasFinance);
const saasCosts=elem('section','');saasCosts.className='workflow-section';saasCosts.id='saas-costs';$('workspace').append(saasCosts);
function renderSaasCosts(items){saasCosts.replaceChildren(elem('h2','Rentabilité SaaS — flux affectés'),elem('p','Depuis l’origine, par devise. Encaissements TTC moins coûts affectés : indicateur de trésorerie, pas marge comptable.'));const wrap=elem('div','');wrap.className='table-wrap';wrap.tabIndex=0;wrap.setAttribute('role','region');wrap.setAttribute('aria-label','Rentabilité SaaS');const table=elem('table',''),head=elem('thead',''),tr=elem('tr',''),body=elem('tbody','');for(const label of ['Produit','Devise','Facturé HT','Encaissé TTC','Infrastructure','Support','Acquisition','Exploitation','Coûts affectés','Flux net affecté']){const th=elem('th',label);th.scope='col';tr.append(th)}head.append(tr);for(const x of items){const r=elem('tr','');for(const k of ['product','currency','invoiced_ht','received_ttc','INFRASTRUCTURE','SUPPORT','ACQUISITION','EXPLOITATION','allocated','cash_contribution'])r.append(elem('td',x[k]));body.append(r)}table.append(head,body);wrap.append(table);saasCosts.append(wrap)}
function renderSaasFinance(values){saasFinance.replaceChildren(elem('h2','Pilotage financier SaaS TTC'),elem('p','Factures rapprochées et règlements réels enregistrés par devise. Hors marges et créances HT des missions. Horizons cumulés hors impayés.'));const wrap=elem('div','');wrap.className='table-wrap';wrap.tabIndex=0;wrap.setAttribute('role','region');wrap.setAttribute('aria-label','Pilotage financier SaaS TTC');const table=elem('table',''),head=elem('thead',''),tr=elem('tr',''),body=elem('tbody','');for(const label of ['Devise','Facturé','Encaissé','Solde','En retard','J+30','J+60','J+90']){const th=elem('th',label);th.scope='col';tr.append(th)}head.append(tr);for(const [currency,x] of Object.entries(values)){const r=elem('tr','');for(const v of [currency,x.invoiced,x.paid,x.balance,x.overdue,x.receipts_30,x.receipts_60,x.receipts_90])r.append(elem('td',v));body.append(r)}table.append(head,body);wrap.append(table);saasFinance.append(wrap)}
function renderControl(){const root=$('control-tables');root.replaceChildren();if(!controlData)return;const currency=$('control-currency').value,q=$('control-search').value.trim().toLocaleLowerCase('fr');for(const [title,items,keys] of [['Synthèse par devise',controlData.currencies,[['currency','Devise']]],['Rentabilité par client',controlData.clients,[['client','Client'],['currency','Devise']]],['Rentabilité par mission',controlData.missions,[['client','Client'],['contract_ref','Contrat'],['title','Mission'],['currency','Devise']]]]){root.append(elem('h3',title));const wrap=document.createElement('div');wrap.className='table-wrap';wrap.tabIndex=0;wrap.setAttribute('role','region');wrap.setAttribute('aria-label',title);const table=document.createElement('table'),thead=document.createElement('thead'),tr=document.createElement('tr'),body=document.createElement('tbody');for(const [,label] of [...keys,...metrics]){const th=elem('th',label);th.scope='col';tr.append(th)}thead.append(tr);table.append(thead,body);for(const x of items){if(currency&&x.currency!==currency)continue;if(q&&x.client&&!((x.client+' '+(x.title||'')+' '+(x.contract_ref||'')).toLocaleLowerCase('fr').includes(q)))continue;const r=document.createElement('tr');for(const [k] of [...keys,...metrics])r.append(elem('td',x[k]??'—'));body.append(r)}if(!body.children.length){const r=document.createElement('tr'),td=elem('td','Aucun résultat.');td.colSpan=keys.length+metrics.length;r.append(td);body.append(r)}wrap.append(table);root.append(wrap)}renderSupplement(root,currency,q);$('control-export').disabled=false;}
function renderSupplement(root,currency,q){for(const [title,items,keys] of [['Flux de trésorerie enregistrés',controlData.cash,[['currency','Devise'],['received','Entrées'],['outflows','Sorties'],['net_flow','Flux net']]],['Analyse individuelle des consultants',controlData.consultants,[['consultant','Consultant'],['title','Mission'],['currency','Devise'],['worked','Jours travaillés'],['billable','Jours facturables'],['cost','Coût direct'],['revenue','CA facturable'],['margin','Marge régie'],['billable_rate','Jours facturables / travaillés (%)'],['margin_rate','Marge régie (%)']]],['Rentabilité par contrat',controlData.contracts,[['client','Client'],['contract_ref','Contrat'],['currency','Devise'],...metrics]]]){root.append(elem('h3',title));const wrap=document.createElement('div');wrap.className='table-wrap';wrap.tabIndex=0;wrap.setAttribute('role','region');wrap.setAttribute('aria-label',title);const table=document.createElement('table'),head=document.createElement('thead'),tr=document.createElement('tr'),body=document.createElement('tbody');for(const [,label] of keys){const th=elem('th',label);th.scope='col';tr.append(th)}head.append(tr);table.append(head,body);for(const x of items){if(currency&&x.currency!==currency)continue;if(q&&x.contract_ref&&!(x.client+' '+x.contract_ref).toLocaleLowerCase('fr').includes(q))continue;if(q&&x.consultant&&!(x.consultant+' '+x.title).toLocaleLowerCase('fr').includes(q))continue;const r=document.createElement('tr');for(const [k] of keys)r.append(elem('td',x[k]??'—'));body.append(r)}if(!body.children.length){const r=document.createElement('tr'),td=elem('td','Aucun résultat.');td.colSpan=keys.length;r.append(td);body.append(r)}wrap.append(table);root.append(wrap)}}
$('control-currency').onchange=renderControl;$('control-search').oninput=renderControl;
async function load(){const e=++epoch;const r=await fetch('/api/admin/direction',{headers:{Authorization:'Bearer '+token}});const d=await r.json();if(!r.ok)throw Error(d.error);if(e!==epoch||!token)return;
 $('date').textContent='Situation au '+d.as_of;$('counts').replaceChildren();$('breakdown').replaceChildren();$('financial').replaceChildren();controlData=d.controlling;renderControl();renderSaasFinance(d.saas_finance);renderSaasCosts(d.saas_profitability);await loadMonthly();if(e!==epoch||!token)return;
 for(const [key,name] of Object.entries(labels)){const values=d.counts[key];const card=elem('div',name);card.className='count';card.prepend(elem('strong',Object.values(values).reduce((a,b)=>a+b,0)));$('counts').append(card);const block=elem('div','');block.className='status-card';block.append(elem('h3',name));const sum=Object.values(values).reduce((a,b)=>a+b,0);for(const [s,n] of Object.entries(values)){const row=elem('div','');row.className='status-row';row.append(elem('span',s+' : '+n));const bar=document.createElement('progress');bar.max=Math.max(1,sum);bar.value=n;bar.setAttribute('aria-label',name+' — '+s);row.append(bar);block.append(row)}$('breakdown').append(block)}
 $('alerts').textContent=d.overdue+' relance(s) en retard ; '+d.ambiguous_opportunities+' opportunité(s) avec plusieurs devis acceptés, exclues des totaux.';
 for(const x of d.financial){const row=document.createElement('tr');for(const k of ['currency','count','revenue','direct_cost','margin'])row.append(elem('td',x[k]));$('financial').append(row)}
 if(!d.financial.length){const row=document.createElement('tr'),td=elem('td','Aucun engagement chiffrable.');td.colSpan=5;row.append(td);$('financial').append(row)}
}
$('login-form').onsubmit=async e=>{e.preventDefault();token=$('token').value;$('token').value='';try{await load();$('login').hidden=true;$('workspace').hidden=false;notice('Connecté.')}catch(e){token='';notice(e.message)}};
$('refresh').onclick=async()=>{try{await load();notice('Actualisé.')}catch(e){notice(e.message)}};
$('logout').onclick=()=>{epoch++;token='';controlData=null;saasFinance.replaceChildren();saasCosts.replaceChildren();$('control-export').disabled=true;$('control-export-notice').textContent='';for(const id of ['counts','breakdown','financial','date','alerts','control-tables'])$(id).replaceChildren();$('control-search').value='';$('control-currency').value='';$('workspace').hidden=true;$('login').hidden=false;notice('Déconnecté.')};

/* Export the rendered, authorized table (never cached across logout). */
function controlCsvCell(value){
 let s=String(value??'');
 if(/^\s*[=+\-@]/u.test(s)&&!/^\s*-?\d+(?:[.,]\d+)?\s*$/u.test(s)||/^[\t\r\n]/u.test(s))s="'"+s;
 return '"'+s.replaceAll('"','""')+'"';
}
$('control-export').onclick=()=>{
 if(!token||!controlData)return;
 const index=Number($('control-export-table').value);
 const tables=$('control-tables').querySelectorAll('table'),table=tables[index];
 if(!table)return;
 const rows=[...table.querySelectorAll('thead tr,tbody tr')].filter(row=>!row.querySelector('td[colspan]'));
 const csv='\uFEFF'+rows.map(row=>Array.from(row.cells,cell=>controlCsvCell(cell.textContent==='—'?'':cell.textContent)).join(';')).join('\r\n')+'\r\n';
 const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');
 link.href=url;link.download='dsig-pilotage-'+['devises','clients','missions','tresorerie','consultants','contrats'][index]+'.csv';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
 $('control-export-notice').textContent=(rows.length-1)+' ligne(s) exportée(s).';
};

// Monthly report: identical restricted API in Finance and Direction.
const monthlySection=document.createElement('section');monthlySection.id='saas-monthly';monthlySection.className='workflow-section';
function monthlyNode(tag,text=''){const e=document.createElement(tag);e.textContent=text;return e}
monthlySection.append(monthlyNode('h2','Performance mensuelle SaaS'),monthlyNode('p','Facturation HT à la date d’émission, encaissements TTC à la date de règlement, coûts à la date du décaissement. Flux net affecté, hors marge comptable. Mois sans mouvement non affichés.'));
const monthlyForm=monthlyNode('form');monthlyForm.className='toolbar';
function monthlyField(label,type){const l=monthlyNode('label',label),e=monthlyNode(type==='month'?'input':'select');if(type==='month'){e.type='month';e.required=true}l.append(e);monthlyForm.append(l);return e}
const monthStart=monthlyField('Mois de début','month'),monthEnd=monthlyField('Mois de fin','month'),monthProduct=monthlyField('Produit SaaS mensuel','select'),monthCurrency=monthlyField('Devise mensuelle','select');
function monthlyDefaults(){const now=new Date();monthStart.value=now.getFullYear()+'-01';monthEnd.value=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0');monthProduct.value='';monthCurrency.value=''}
monthProduct.append(new Option('Tous les produits',''));for(const c of ['','EUR','GNF','XOF','USD'])monthCurrency.append(new Option(c||'Toutes les devises',c));monthlyDefaults();
const monthApply=monthlyNode('button','Afficher la période'),monthExport=monthlyNode('button','Exporter la période (CSV)');monthExport.type='button';monthExport.disabled=true;monthlyForm.append(monthApply,monthExport);monthlySection.append(monthlyForm);
const monthHeaders=['Mois','Produit','Devise','Facturé HT','Encaissé TTC','Infrastructure','Support','Acquisition','Exploitation','Coûts affectés','Flux net affecté'];
const monthKeys=['month','product','currency','invoiced_ht','received_ttc','INFRASTRUCTURE','SUPPORT','ACQUISITION','EXPLOITATION','allocated','cash_contribution'];
const monthWrap=monthlyNode('div');monthWrap.className='table-wrap';monthWrap.tabIndex=0;monthWrap.setAttribute('role','region');monthWrap.setAttribute('aria-label','Performance mensuelle SaaS');const monthTable=monthlyNode('table'),monthHead=monthlyNode('thead'),monthTr=monthlyNode('tr'),monthBody=monthlyNode('tbody');for(const label of monthHeaders){const th=monthlyNode('th',label);th.scope='col';monthTr.append(th)}monthHead.append(monthTr);monthTable.append(monthHead,monthBody);monthWrap.append(monthTable);monthlySection.append(monthWrap);
const monthPrev=monthlyNode('button','Précédent'),monthNext=monthlyNode('button','Suivant'),monthStatus=monthlyNode('span'),monthNav=monthlyNode('div');monthNav.className='toolbar';monthNav.append(monthPrev,monthStatus,monthNext);monthlySection.append(monthNav);
let monthRows=[],monthPage=1,monthEpoch=0;
function monthlyRender(){monthBody.replaceChildren();for(const x of monthRows.slice((monthPage-1)*10,monthPage*10)){const tr=monthlyNode('tr');for(const k of monthKeys)tr.append(monthlyNode('td',x[k]));monthBody.append(tr)}monthStatus.textContent='Page '+monthPage+' · '+monthRows.length+' ligne(s)';monthPrev.disabled=monthPage===1;monthNext.disabled=monthPage*10>=monthRows.length;monthExport.disabled=!monthRows.length}
async function loadMonthly(){const id=++monthEpoch,t=token;monthRows=[];monthPage=1;monthlyRender();const q=new URLSearchParams({start:monthStart.value,end:monthEnd.value,product:monthProduct.value,currency:monthCurrency.value});const r=await fetch('/api/admin/direction/saas-monthly?'+q,{headers:{Authorization:'Bearer '+t}});const d=await r.json();if(id!==monthEpoch||!token||t!==token)return;if(!r.ok)throw Error(d.error);const p=monthProduct.value;monthProduct.replaceChildren(new Option('Tous les produits',''));for(const [id,name] of Object.entries(d.products))monthProduct.append(new Option(name,id));monthProduct.value=p;monthRows=d.items;monthlyRender()}
monthlyForm.onsubmit=async e=>{e.preventDefault();if(token)try{await loadMonthly()}catch(e){notice(e.message)}};
for(const f of [monthStart,monthEnd,monthProduct,monthCurrency])f.onchange=()=>{monthEpoch++;monthRows=[];monthPage=1;monthlyRender()};
monthPrev.onclick=()=>{if(token&&monthPage>1){monthPage--;monthlyRender()}};monthNext.onclick=()=>{if(token&&!monthNext.disabled){monthPage++;monthlyRender()}};
monthExport.onclick=()=>{if(!token||!monthRows.length)return;const esc=v=>{let s=String(v??'');if(/^[\s]*[=+\-@]/.test(s)||/^[\t\r\n]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};const csv=[monthHeaders,...monthRows.map(x=>monthKeys.map(k=>x[k]))].map(r=>r.map(esc).join(';')).join('\r\n');const a=monthlyNode('a'),url=URL.createObjectURL(new Blob(['\uFEFF',csv],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='dsig-performance-saas.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('logout').addEventListener('click',()=>{monthEpoch++;monthRows=[];monthPage=1;monthlyDefaults();monthlyRender()});
saasCosts.after(monthlySection);
